110: void SetupExitCallback(Napi::Env env, Napi::Function cb, pid_t pid) {
111:   std::thread *th = new std::thread;
112:   // Don't use Napi::AsyncWorker which is limited by UV_THREADPOOL_SIZE.
113:   auto tsfn = Napi::ThreadSafeFunction::New(
114:       env,
115:       cb,                           // JavaScript function called asynchronously
116:       "SetupExitCallback_resource", // Name
117:       0,                            // Unlimited queue
118:       1,                            // Only one thread will use this initially
119:       [th](Napi::Env) {   // Finalizer used to clean threads up
120:         th->join();
121:         delete th;
122:       });
123:   *th = std::thread([tsfn = std::move(tsfn), pid] {
124:     auto callback = [](Napi::Env env, Napi::Function cb, ExitEvent *exit_event) {
125:       cb.Call({Napi::Number::New(env, exit_event->exit_code),
126:                Napi::Number::New(env, exit_event->signal_code)});
127:       delete exit_event;
128:     };
129: 
130:     int ret;
131:     int stat_loc;
132: #if defined(__APPLE__)
133:     // Based on
134:     // https://source.chromium.org/chromium/chromium/src/+/main:base/process/kill_mac.cc;l=35-69?
135:     int kq = HANDLE_EINTR(kqueue());
136:     struct kevent change = {0};
137:     EV_SET(&change, pid, EVFILT_PROC, EV_ADD, NOTE_EXIT, 0, NULL);
138:     ret = HANDLE_EINTR(kevent(kq, &change, 1, NULL, 0, NULL));
139:     if (ret == -1) {
140:       if (errno == ESRCH) {
141:         // At this point, one of the following has occurred:
142:         // 1. The process has died but has not yet been reaped.
143:         // 2. The process has died and has already been reaped.
144:         // 3. The process is in the process of dying. It's no longer
145:         //    kqueueable, but it may not be waitable yet either. Mark calls
146:         //    this case the "zombie death race".
147:         ret = HANDLE_EINTR(waitpid(pid, &stat_loc, WNOHANG));
148:         if (ret == 0) {
149:           ret = kill(pid, SIGKILL);
150:           if (ret != -1) {
151:             HANDLE_EINTR(waitpid(pid, &stat_loc, 0));
152:           }
153:         }
154:       }
155:     } else {
156:       struct kevent event = {0};
157:       ret = HANDLE_EINTR(kevent(kq, NULL, 0, &event, 1, NULL));
158:       if (ret == 1) {
159:         if ((event.fflags & NOTE_EXIT) &&
160:             (event.ident == static_cast<uintptr_t>(pid))) {
161:           // The process is dead or dying. This won't block for long, if at
162:           // all.
163:           HANDLE_EINTR(waitpid(pid, &stat_loc, 0));
164:         }
165:       }
166:     }
167: #else
168:     while (true) {
169:       errno = 0;
170:       if ((ret = waitpid(pid, &stat_loc, 0)) != pid) {
171:         if (ret == -1 && errno == EINTR) {
172:           continue;
173:         }
174:         if (ret == -1 && errno == ECHILD) {
175:           // XXX node v0.8.x seems to have this problem.
176:           // waitpid is already handled elsewhere.
177:           ;
178:         } else {
179:           assert(false);
180:         }
181:       }
182:       break;
183:     }
184: #endif
185:     ExitEvent *exit_event = new ExitEvent;
186:     if (WIFEXITED(stat_loc)) {
187:       exit_event->exit_code = WEXITSTATUS(stat_loc); // errno?
188:     }
189:     if (WIFSIGNALED(stat_loc)) {
190:       exit_event->signal_code = WTERMSIG(stat_loc);
191:     }
192:     auto status = tsfn.BlockingCall(exit_event, callback); // In main thread
193:     switch (status) {
194:       case napi_closing:
195:         break;
196: 
197:       case napi_queue_full:
198:         Napi::Error::Fatal("SetupExitCallback", "Queue was full");
199: 
200:       case napi_ok:
201:         if (tsfn.Release() != napi_ok) {
202:           Napi::Error::Fatal("SetupExitCallback", "ThreadSafeFunction.Release() failed");
203:         }
204:         break;
205: 
206:       default:
207:         Napi::Error::Fatal("SetupExitCallback", "ThreadSafeFunction.BlockingCall() failed");
208:     }
209:   });
210: }
