741:   posix_spawn_file_actions_t acts;
742:   posix_spawn_file_actions_init(&acts);
743:   posix_spawn_file_actions_adddup2(&acts, slave, STDIN_FILENO);
744:   posix_spawn_file_actions_adddup2(&acts, slave, STDOUT_FILENO);
